<?php require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();if(!empty($_SESSION['admin_id']))redirect('dashboard.php');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';else{if(!login_rate_allowed('admin',trim($_POST['email']??''))){$error='Too many login attempts. Please try again later.';}else{try{$pdo=db();$st=$pdo->prepare("SELECT * FROM admin_users WHERE email=? AND status='active' LIMIT 1");$st->execute([trim($_POST['email']??'')]);$a=$st->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){record_login_attempt('admin',trim($_POST['email']??''),true);rotate_session_on_login();$_SESSION['admin_id']=$a['id'];$_SESSION['admin_role']=$a['role'];$pdo->prepare("UPDATE admin_users SET last_login=NOW() WHERE id=?")->execute([$a['id']]);redirect('dashboard.php');}else{record_login_attempt('admin',trim($_POST['email']??''),false);$error='Invalid admin credentials.';}}catch(Throwable $e){$error='Database configuration issue.';}}}}$page_title='Admin Login';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?><div class="form-wrap"><div class="form-card"><h1>Admin Login</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn btn-primary full">Admin Login</button></form></div></div><?php require '../includes/footer.php';?>